# Dataset Join Recommender - runnable demo (JAH-ATK192-000001)
RANK = 1
SIG = False
DS_A, DS_B = [('orders', {'cust_id': [1, 2, 3], 'total': [50, 60, 70]}), ('customers', {'cust_id': [1, 2, 3, 4], 'name': ['a', 'b', 'c', 'd']})]  # (name, {field: [values]})
def overlap(a, b):
    a, b = set(a), set(b)
    return len(a & b)/len(a | b) if a | b else 0.0
recs = []
for fa, va in DS_A[1].items():
    for fb, vb in DS_B[1].items():
        ov = overlap(va, vb)
        uniq_a = len(set(va)) == len(va); uniq_b = len(set(vb)) == len(vb)
        score = 0.6*ov + 0.2*uniq_a + 0.2*uniq_b
        if ov > 0: recs.append((fa, fb, round(score, 2), ov, uniq_a and uniq_b))
recs.sort(key=lambda x: -x[2])
print("join %s x %s:" % (DS_A[0], DS_B[0]))
for fa, fb, s, ov, pk in recs:
    print("  %-8s = %-8s score=%.2f overlap=%.2f %s" % (fa, fb, s, ov, "KEY?" if pk else ""))
if not recs: print("  no joinable fields found")
if RANK >= 3: print("candidate pairs scored:", len(recs))
if SIG:
    print("Signature lineage stamp: JAH-SIG-JON-" + "JAH-ATK192-000001")
print("record:", "JAH-ATK192-000001", "OK")

